  @protected
  void sse_encode_sync_event(SyncEvent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case SyncEvent_Connecting():
        sse_encode_i_32(0, serializer);
      case SyncEvent_Downloading(what: final what):
        sse_encode_i_32(1, serializer);
        sse_encode_String(what, serializer);
      case SyncEvent_Saving():
        sse_encode_i_32(2, serializer);
      case SyncEvent_Done(source: final source):
        sse_encode_i_32(3, serializer);
        sse_encode_box_autoadd_source_info(source, serializer);
      case SyncEvent_Failed(message: final message):
        sse_encode_i_32(4, serializer);
        sse_encode_String(message, serializer);
    }
  }

